const cgStop=new Set('le la les un une des de du d au aux et ou en dans sur sous pour par avec sans ce cet cette ces il elle ils elles on nous vous je tu se sa son ses leur leurs que qui quoi dont où est sont être a ont avoir fait faire plus moins très ne pas mais comme si y à l au d qu c j n s t m votre vos notre nos leur leurs quel quelle quels quelles selon après avant entre vers chez puis donc car'.split(/\s+/));
function cgWords(s){return (String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').match(/[a-z0-9]+/g)||[]).filter(w=>w.length>2&&!cgStop.has(w))}
function cgSentences(s){return String(s||'').replace(/\s+/g,' ').split(/(?<=[.!?…])\s+|\n+/).map(x=>x.trim()).filter(x=>x.length>12)}
function chatGPTExplanation(q){
  const ci=q.options.findIndex(o=>o.correct), answer=q.options[ci]?.label||'', letter=String.fromCharCode(65+ci);
  let source=q.content||q.explanation||'';
  source=source.replace(/^(Explication|Explanation)\s*:\s*/i,'').replace(/Transcription\s*:\s*/ig,'');
  const aw=new Set(cgWords(answer)), ew=new Set(cgWords(q.explanation||''));
  const scored=cgSentences(source).map((s,i)=>{
    const sw=new Set(cgWords(s)); let score=0;
    aw.forEach(w=>{if(sw.has(w))score+=4}); ew.forEach(w=>{if(sw.has(w))score+=1});
    if(/mais|pourtant|cependant|donc|ainsi|car|parce|selon|vise|permet|demande|important|seulement|réserv|impact|juste|exigeant/i.test(s))score+=1.5;
    return {s,score,i};
  }).sort((a,b)=>b.score-a.score||a.i-b.i);
  let keys=scored.filter(x=>x.score>0).slice(0,2).sort((a,b)=>a.i-b.i).map(x=>x.s);
  if(!keys.length) keys=cgSentences(source).slice(0,2);
  const wrong=q.options.map((o,i)=>({o,i})).filter(x=>x.i!==ci);
  let trap=wrong[0]?.o.label||'';
  if(wrong.length){const kw=new Set(cgWords(keys.join(' ')));wrong.sort((a,b)=>cgWords(b.o.label).filter(w=>kw.has(w)).length-cgWords(a.o.label).filter(w=>kw.has(w)).length);trap=wrong[0].o.label}
  const keyHtml=keys.length?keys.map(k=>`<div style="margin:5px 0"><b>« ${esc(k)} »</b></div>`).join(''):'<div>The answer comes from the overall meaning of the passage/transcription.</div>';
  const relation=keys.length?`These words point to <b>${esc(answer)}</b>. The correct option restates the idea of the source rather than necessarily repeating the same vocabulary.`:`The overall message corresponds best to <b>${esc(answer)}</b>.`;
  return `<div class="explain chatgpt-explain" style="margin-top:14px;border-left:4px solid #10a37f;padding-left:16px">
    <div style="font-size:1.05em;margin-bottom:10px"><b>ChatGPT · Detailed answer analysis</b></div>
    <div><b>Correct answer:</b><br><b>${letter}. ${esc(answer)}</b></div>
    <div style="margin-top:10px"><b>Key phrase${keys.length===1?'':'s'}:</b>${keyHtml}</div>
    <div style="margin-top:10px"><b>Why this is correct:</b><br>${relation}</div>
    <div style="margin-top:10px"><b>Paraphrase / connection:</b><br>${keys.length?`<b>${esc(keys[0])}</b> → <b>${esc(answer)}</b>`:`main idea → <b>${esc(answer)}</b>`}</div>
    ${trap?`<div style="margin-top:10px"><b>Trap to avoid:</b><br><b>${esc(trap)}</b> is not the best answer because it does not express the central idea supported by the key phrase(s) above.</div>`:''}
    <div style="margin-top:10px"><b>TCF strategy:</b><br>Match the <b>meaning</b>, not just identical words. Find the sentence that directly answers the question, then choose the option that paraphrases it most precisely.</div>
  </div>`;
}


// Practice-only scoring model. FEI does not publish official per-question point values.
// This estimate totals 699 points: Q1-4=3, Q5-10=9, Q11-19=15, Q20-29=21, Q30-35=26, Q36-39=33.
function questionPoints(index){const n=index+1;return n<=4?3:n<=10?9:n<=19?15:n<=29?21:n<=35?26:33}
